import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.Sdx4l2LO.js";const u=JSON.parse('{"title":"ADR-014: DINO Runtime Execution Model Discovery","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-014-runtime-execution-model.md","filePath":"adr/ADR-014-runtime-execution-model.md","lastUpdated":1774803703000}'),n={name:"adr/ADR-014-runtime-execution-model.md"};function r(d,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-014-dino-runtime-execution-model-discovery" tabindex="-1">ADR-014: DINO Runtime Execution Model Discovery <a class="header-anchor" href="#adr-014-dino-runtime-execution-model-discovery" aria-label="Permalink to &quot;ADR-014: DINO Runtime Execution Model Discovery&quot;">​</a></h1><h2 id="status-accepted" tabindex="-1">Status: Accepted <a class="header-anchor" href="#status-accepted" aria-label="Permalink to &quot;Status: Accepted&quot;">​</a></h2><h2 id="date-2026-03-24" tabindex="-1">Date: 2026-03-24 <a class="header-anchor" href="#date-2026-03-24" aria-label="Permalink to &quot;Date: 2026-03-24&quot;">​</a></h2><h2 id="deciders" tabindex="-1">Deciders <a class="header-anchor" href="#deciders" aria-label="Permalink to &quot;Deciders&quot;">​</a></h2><p>kooshapari</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>DINOForge is a BepInEx plugin that runs inside Diplomacy is Not an Option (DINO), a Unity 2021.3.45f2 game using Unity DOTS (ECS) with the Mono scripting backend. Standard BepInEx plugin authoring assumes that <code>MonoBehaviour.Update()</code> and Unity&#39;s PlayerLoop will drive per-frame callbacks. DINO violates this assumption entirely.</p><h3 id="what-was-discovered" tabindex="-1">What was discovered <a class="header-anchor" href="#what-was-discovered" aria-label="Permalink to &quot;What was discovered&quot;">​</a></h3><p>DINO replaces Unity&#39;s PlayerLoop with a custom ECS scheduler driven by <code>GameStateSystems.GameStateUpdateHandler</code> and <code>[RuntimeInitializeOnLoadMethod]</code>. As a result, the following <strong>never fire</strong> inside DINO (confirmed by zero log output after <code>Awake()</code>):</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Why it fails</th></tr></thead><tbody><tr><td><code>MonoBehaviour.Update()</code></td><td>DINO&#39;s scheduler replaces the Unity PlayerLoop; the default Update phase is not called</td></tr><tr><td><code>MonoBehaviour.OnGUI()</code></td><td>Suppressed — no IMGUI pass in DINO&#39;s ECS renderer path</td></tr><tr><td><code>PlayerLoop.Update</code> subsystem callbacks (naive injection)</td><td>Injected at boot, but DINO later calls <code>PlayerLoop.SetPlayerLoop()</code> which overwrites the loop, evicting all injected entries</td></tr><tr><td><code>Application.onBeforeRender</code></td><td>Fires 3 times at boot then stops permanently</td></tr><tr><td><code>Camera.onPreCull</code></td><td>No cameras exist in DINO&#39;s ECS renderer path after boot</td></tr><tr><td><code>World.Update()</code> Harmony patch (abstract)</td><td>The abstract base is never called directly — DINO uses concrete subclasses</td></tr><tr><td><code>ComponentSystemGroup.Update()</code> Harmony patch (abstract)</td><td>Same; abstract base not dispatched directly</td></tr><tr><td><code>Time.get_deltaTime</code> Harmony patch</td><td>C++ icall; cannot be intercepted by managed Harmony</td></tr><tr><td><code>KeyInputSystem.OnUpdate()</code> via ECS</td><td>System is created and added to <code>InitializationSystemGroup</code>, but DINO&#39;s custom scheduler does not tick this group in its standard loop</td></tr><tr><td><code>SceneManager.sceneLoaded</code> callbacks</td><td>Fires during scene teardown when the Mono delegate machinery is in a corrupt state; even a no-op callback can trigger crashes in other listeners</td></tr></tbody></table><p>The following <strong>do fire</strong> (confirmed working):</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>When</th></tr></thead><tbody><tr><td><code>MonoBehaviour.Awake()</code> / <code>OnEnable()</code></td><td>Synchronously from <code>AddComponent()</code> — one-time at boot</td></tr><tr><td><code>MonoBehaviour.OnDestroy()</code></td><td>At frame 0, as DINO sweeps its scene hierarchy</td></tr><tr><td><code>SystemBase.OnCreate()</code></td><td>Synchronously during world creation</td></tr><tr><td>Win32 background thread (<code>GetAsyncKeyState</code>, <code>Thread.Sleep</code>)</td><td>Indefinitely; DINO does not interfere with native threads</td></tr><tr><td><code>FightGroup.OnUpdate()</code> Harmony postfix</td><td>Every gameplay frame; DINO&#39;s scheduler calls this concrete managed type</td></tr><tr><td><code>GameplayInitializationSystemsGroup.OnUpdate()</code> Harmony postfix</td><td>Every gameplay frame (earlier in frame than FightGroup)</td></tr><tr><td><code>PathFindingGroup.OnUpdate()</code> Harmony postfix</td><td>Every gameplay frame</td></tr><tr><td><code>PlayerLoop.SetPlayerLoop()</code> Harmony postfix</td><td>Every time DINO rebuilds its player loop (used to re-inject our entries)</td></tr></tbody></table><h3 id="why-the-bepinex-managed-plugin-object-dies" tabindex="-1">Why the BepInEx-managed plugin object dies <a class="header-anchor" href="#why-the-bepinex-managed-plugin-object-dies" aria-label="Permalink to &quot;Why the BepInEx-managed plugin object dies&quot;">​</a></h3><p>DINO&#39;s scene loader destroys all non-essential <code>MonoBehaviour</code> objects at frame 0, including the BepInEx-managed <code>Plugin</code> gameObject, even when <code>DontDestroyOnLoad</code> is set. A separate <code>DINOForge_Root</code> <code>GameObject</code> created with <code>HideFlags.HideAndDontSave | DontDestroyOnLoad</code> survives this sweep.</p><h3 id="why-resources-findobjectsoftypeall-is-banned-from-background-threads" tabindex="-1">Why <code>Resources.FindObjectsOfTypeAll</code> is banned from background threads <a class="header-anchor" href="#why-resources-findobjectsoftypeall-is-banned-from-background-threads" aria-label="Permalink to &quot;Why `Resources.FindObjectsOfTypeAll` is banned from background threads&quot;">​</a></h3><p>Calling <code>Resources.FindObjectsOfTypeAll&amp;lt;Canvas&amp;gt;()</code> from a background thread deadlocks during Unity&#39;s asset-loading phase (<code>InitialGameLoader</code> scene). This is a Unity internal lock conflict and cannot be worked around without blocking the game indefinitely.</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><h3 id="_1-abandon-monobehaviour-update-for-per-frame-work" tabindex="-1">1. Abandon <code>MonoBehaviour.Update()</code> for per-frame work <a class="header-anchor" href="#_1-abandon-monobehaviour-update-for-per-frame-work" aria-label="Permalink to &quot;1. Abandon `MonoBehaviour.Update()` for per-frame work&quot;">​</a></h3><p><code>MonoBehaviour.Update()</code> is unreliable in DINO. Any feature requiring per-frame execution must use one of the verified mechanisms below.</p><h3 id="_2-win32-background-thread-for-f9-f10-key-detection" tabindex="-1">2. Win32 background thread for F9/F10 key detection <a class="header-anchor" href="#_2-win32-background-thread-for-f9-f10-key-detection" aria-label="Permalink to &quot;2. Win32 background thread for F9/F10 key detection&quot;">​</a></h3><p>A dedicated background thread polls <code>GetAsyncKeyState(VK_F9)</code> and <code>GetAsyncKeyState(VK_F10)</code> every 50 ms (20 Hz). On a falling-edge transition, the thread directly invokes <code>KeyInputSystem.OnF9Pressed</code> and <code>KeyInputSystem.OnF10Pressed</code> static delegates.</p><p><strong>Why this is safe:</strong> Unity 2021.3 on Mono does not enforce main-thread checks on <code>SetActive()</code> calls for <code>HideAndDontSave / DontDestroyOnLoad</code> objects. Invoking a static C# delegate is inherently thread-safe. The delegates themselves call Unity UI code on whatever thread they run on; the RuntimeDriver handlers are designed to be idempotent and do not depend on main-thread-only Unity APIs.</p><p><strong>Why not Unity <code>Input</code> APIs from this thread:</strong> <code>Input.GetKeyDown()</code> is a Unity main-thread API and will produce undefined behavior or throw when called from a background thread.</p><h3 id="_3-playerloop-injection-as-primary-fallback" tabindex="-1">3. PlayerLoop injection as primary fallback <a class="header-anchor" href="#_3-playerloop-injection-as-primary-fallback" aria-label="Permalink to &quot;3. PlayerLoop injection as primary fallback&quot;">​</a></h3><p>At boot (<code>Awake()</code>), and again after every <code>PlayerLoop.SetPlayerLoop()</code> call (intercepted via a Harmony postfix), a <code>DINOForgeUpdate</code> entry is inserted into Unity&#39;s <code>Update</code> subsystem. This entry calls <code>DINOForgePlayerLoopUpdate()</code> which:</p><ul><li>Checks <code>Input.GetKeyDown(F9/F10)</code> and dispatches to <code>KeyInputSystem</code></li><li>Checks <code>NeedsResurrection</code> and calls <code>TryResurrect</code></li><li>Runs <code>OnBeforeRenderWorldScan</code> to detect new ECS worlds</li></ul><p><strong>Why Harmony re-injection is needed:</strong> DINO rebuilds the PlayerLoop during world teardown and creation. A naive one-time injection at boot is evicted when DINO calls <code>SetPlayerLoop</code>. The Harmony postfix on <code>SetPlayerLoop</code> ensures our entry is re-appended after every such rebuild. A reentrancy guard (<code>_reinjecting</code> / <code>_injectingNow</code>) prevents the postfix from recursing when our own re-injection calls <code>SetPlayerLoop</code>.</p><h3 id="_4-fightgroup-harmony-patch-for-gameplay-phase-detection" tabindex="-1">4. FightGroup Harmony patch for gameplay-phase detection <a class="header-anchor" href="#_4-fightgroup-harmony-patch-for-gameplay-phase-detection" aria-label="Permalink to &quot;4. FightGroup Harmony patch for gameplay-phase detection&quot;">​</a></h3><p>A Harmony postfix on <code>Systems.ComponentSystemGroups.FightGroup.OnUpdate()</code> (located in <code>DNO.Main.dll</code>) provides a guaranteed per-frame main-thread execution context during active gameplay. This is the most reliable mechanism for resurrection and key detection while the user is playing.</p><p><strong>Why FightGroup specifically:</strong></p><ul><li><code>FightGroup</code> is a concrete managed <code>ComponentSystemGroup</code> subclass — Harmony can intercept it.</li><li>It runs inside <code>SimulationSystemGroup</code> every gameplay frame.</li><li>It does not run on the main menu, which is acceptable since UI overlays are only useful during gameplay.</li><li><code>GameplayInitializationSystemsGroup</code> is patched first in the priority list as it fires earlier in the frame; <code>FightGroup</code> is the primary fallback if the initialization group is not found.</li></ul><p><strong>Why the abstract base class cannot be patched:</strong> Harmony patches apply to individual method slots on types. <code>ComponentSystemGroup.OnUpdate()</code> is abstract; patching the abstract declaration does not intercept overrides in concrete subclasses. Each concrete DINO group must be patched individually.</p><h3 id="_5-needsresurrection-flag-tryresurrect-for-monobehaviour-lifecycle-recovery" tabindex="-1">5. <code>NeedsResurrection</code> flag + <code>TryResurrect</code> for MonoBehaviour lifecycle recovery <a class="header-anchor" href="#_5-needsresurrection-flag-tryresurrect-for-monobehaviour-lifecycle-recovery" aria-label="Permalink to &quot;5. `NeedsResurrection` flag + `TryResurrect` for MonoBehaviour lifecycle recovery&quot;">​</a></h3><p>When <code>RuntimeDriver.OnDestroy()</code> fires (frame 0, main thread), it sets <code>Plugin.NeedsResurrection = true</code>. The resurrection is then performed by whichever execution context fires next (PlayerLoop, FightGroup postfix, KeyInputSystem <code>OnUpdate</code>, or the background watcher triggering a main-thread-guarded call). <code>TryResurrect</code> is guarded:</p><ul><li>Main-thread check: if called from a background thread, sets <code>NeedsResurrection = true</code> and returns.</li><li>Max-attempt cap (3): prevents infinite resurrection loops if the underlying cause is fatal.</li><li>Idempotency: checks <code>PersistentRoot != null</code> before creating a new object.</li></ul><hr><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li>F9/F10 key input works at any point in the game lifecycle, including the main menu and during scene transitions.</li><li>Resurrection of <code>DINOForge_Root</code> is automatic and requires no user action.</li><li>The system degrades gracefully: each mechanism is independent; failure of one does not disable the others.</li><li>Observability is high: every execution path writes timestamped heartbeat entries to <code>dinoforge_debug.log</code>.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li>The Win32 background thread invokes C# delegates cross-thread; handlers must be written to tolerate cross-thread invocation or marshal to the main thread explicitly.</li><li>The Harmony postfix on <code>PlayerLoop.SetPlayerLoop</code> adds overhead to every player loop rebuild (typically infrequent, ~seconds apart).</li><li>The FightGroup patch only fires during gameplay, not on the main menu. Resurrection during main-menu-only sessions depends on the PlayerLoop injection path.</li><li>All resurrection paths using Unity APIs are guarded by a main-thread ID check captured at <code>Awake()</code>. If <code>_mainThreadId</code> is not set (edge case: <code>Awake</code> never called), the guard is bypassed.</li></ul><h3 id="neutral" tabindex="-1">Neutral <a class="header-anchor" href="#neutral" aria-label="Permalink to &quot;Neutral&quot;">​</a></h3><ul><li><code>SceneManager.sceneLoaded</code> and <code>activeSceneChanged</code> callbacks are explicitly not used, diverging from standard BepInEx plugin practice.</li><li><code>Application.onBeforeRender</code> is registered as a belt-and-suspenders callback but is expected to be unreliable after boot.</li></ul><hr><h2 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation Notes&quot;">​</a></h2><h3 id="execution-context-priority-highest-confidence-to-lowest" tabindex="-1">Execution context priority (highest confidence to lowest) <a class="header-anchor" href="#execution-context-priority-highest-confidence-to-lowest" aria-label="Permalink to &quot;Execution context priority (highest confidence to lowest)&quot;">​</a></h3><ol><li><code>FightGroup.OnUpdate()</code> Harmony postfix — gameplay only, highest reliability during play</li><li><code>PlayerLoop.Update</code> injected entry (<code>DINOForgeUpdate</code>) — re-injected after every loop rebuild</li><li><code>KeyInputSystem.OnUpdate()</code> ECS path — only fires if DINO&#39;s scheduler happens to tick <code>InitializationSystemGroup</code></li><li><code>Camera.onPreCull</code> — registered as extra belt-and-suspenders; may not fire</li><li>Win32 background thread — runs always; cannot call Unity APIs directly</li><li><code>Application.onBeforeRender</code> — fires at boot only; unreliable beyond frame 3</li></ol><h3 id="key-constants" tabindex="-1">Key constants <a class="header-anchor" href="#key-constants" aria-label="Permalink to &quot;Key constants&quot;">​</a></h3><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VK_F9</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x78</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Win32 virtual key code for F9</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> VK_F10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0x79</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Win32 virtual key code for F10</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaxResurrectionAttempts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BackgroundThreadPollIntervalMs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 20 Hz</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HeartbeatInterval</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// frames (~10s at 60 FPS)</span></span></code></pre></div><h3 id="thread-safety-contract" tabindex="-1">Thread safety contract <a class="header-anchor" href="#thread-safety-contract" aria-label="Permalink to &quot;Thread safety contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Writer thread</th><th>Reader threads</th></tr></thead><tbody><tr><td><code>Plugin.NeedsResurrection</code></td><td>Background watcher, OnDestroy</td><td>PlayerLoop, FightGroup postfix, KeyInputSystem</td></tr><tr><td><code>Plugin.PersistentRoot</code></td><td>Main thread (TryResurrect)</td><td>Background watcher (via <code>ReferenceEquals</code> only)</td></tr><tr><td><code>Plugin.PendingF9Toggle</code></td><td>Background watcher</td><td>(consumed in RuntimeDriver.Update if active)</td></tr><tr><td><code>KeyInputSystem.OnF9Pressed</code></td><td>Plugin.Awake (main thread)</td><td>Background watcher, PlayerLoop</td></tr></tbody></table><p><code>NeedsResurrection</code> and <code>PendingF9Toggle</code> / <code>PendingF10Toggle</code> are declared <code>volatile</code>. <code>PersistentRoot</code> writes are main-thread-only; background reads use <code>System.Object.ReferenceEquals</code> (never Unity&#39;s <code>==</code> operator, which calls <code>UnityEngine.Object.op_Equality</code> and is not thread-safe).</p><h3 id="debug-log-location" tabindex="-1">Debug log location <a class="header-anchor" href="#debug-log-location" aria-label="Permalink to &quot;Debug log location&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;BepInEx root&gt;/dinoforge_debug.log</span></span></code></pre></div><p>Log writes are protected by <code>Monitor.TryEnter</code> with a 100 ms timeout to prevent deadlocks between the main thread and the background watcher thread.</p><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><code>src/Runtime/Plugin.cs</code> — Bootstrap, resurrection, PlayerLoop injection, FightGroup patch, Win32 thread</li><li><code>src/Runtime/Bridge/KeyInputSystem.cs</code> — ECS system, PlayerLoop injection (secondary), F9/F10 dispatch</li><li><code>docs/adr/ADR-005-ecs-integration-strategy.md</code> — ECS bridge strategy context</li><li><code>docs/adr/ADR-009-runtime-orchestration.md</code> — ModPlatform lifecycle coordination</li><li><code>C:\\Users\\koosh\\.claude\\projects\\C--Users-koosh-Dino\\memory\\project_dino_runtime_execution_model.md</code> — Confirmed runtime facts (2026-03-21)</li><li>Unity Entities 0.51 / DOTS documentation: <code>SystemBase</code>, <code>InitializationSystemGroup</code>, <code>PlayerLoop</code></li><li>BepInEx 5.4.23.5 documentation: plugin lifecycle, <code>BaseUnityPlugin</code></li><li>HarmonyX documentation: <code>Harmony.Patch</code>, <code>HarmonyMethod</code>, postfix delegates</li></ul>',60)])])}const y=t(n,[["render",r]]);export{u as __pageData,y as default};
